#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
# Reporting rules (HANDOFF.md): one line per SKU appearing in movements.log
# (net may be 0), plus every catalog SKU even with no movements (SKU-9).
{
  awk 'BEGIN { net["SKU-9"] = 0 }
       { if (!($1 in net)) net[$1] = 0
         net[$1] += ($2 == "receipt" ? $3 : -$3) }
       END { for (sku in net) print sku, net[sku] }' movements.log
} | sort > stock.txt
